// Extraire le titre (première ligne du texte)
const firstLine = extractedText.split('\n')[0];

// Nettoyer pour créer un nom de fichier valide
// Enlever les caractères spéciaux, garder juste lettres, chiffres, espaces et tirets
const cleanFileName = firstLine
  .replace(/[^a-zA-Z0-9\sàâäéèêëïîôùûüç\-]/g, '') // Garde lettres FR + chiffres + espaces + tirets
  .trim()
  .substring(0, 50); // Limite à 50 caractères

return [{
  json: {
    extractedText: extractedText,
    courseTitle: cleanFileName, // Nom de fichier propre
    keywords: firstLine // Le titre brut comme mot-clé
  }
}];

const data = $input.first().json;

// Récupérer le texte produit par OpenAI
let responseText =
    data.output_text ??
    data.output?.[0]?.content?.[0]?.text ??
    data.text ??
    "";

if (!responseText) {
    throw new Error(
        "Aucun texte trouvé dans la réponse OpenAI.\n\nRéponse reçue :\n" +
        JSON.stringify(data, null, 2)
    );
}

// Convertir en texte si nécessaire
responseText = String(responseText).trim();

// Supprimer éventuellement ```json ... ```
responseText = responseText
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

// Extraire uniquement le JSON
const start = responseText.indexOf("{");
const end = responseText.lastIndexOf("}");

if (start === -1 || end === -1) {
    throw new Error(
        "OpenAI n'a pas renvoyé de JSON.\n\nRéponse :\n" +
        responseText
    );
}

responseText = responseText.substring(start, end + 1);

let result;

try {
    result = JSON.parse(responseText);
} catch (error) {
    throw new Error(
        "JSON invalide renvoyé par OpenAI.\n\n" +
        responseText +
        "\n\nErreur : " +
        error.message
    );
}

// Vérification
if (!result.title) {
    throw new Error("Le champ 'title' est manquant.");
}

if (!result.correctedText) {
    throw new Error("Le champ 'correctedText' est manquant.");
}

return [
    {
        json: {
            title: result.title.trim(),
            correctedText: result.correctedText.trim()
        }
    }
];

